const contactForm=document.getElementById("contact-form");contactForm.addEventListener("submit",function(e){e.preventDefault();let s=document.getElementById("form-output-global");if(s.classList.remove("error","success"),this.classList.add("form-in-process"),s.innerHTML='<p><span class="icon text-middle spin icon-spin icon-xxs"></span><span>Sending</span></p>',s.classList.add("active"),this.checkValidity()){const e=grecaptcha.getResponse();if(""===e);else{const t="https://europe-central2-luxurystayskapanaplovdiv.cloudfunctions.net/api/sendMail";let a=contactForm.querySelector("#subject").value,c=contactForm.querySelector("#name").value,n=contactForm.querySelector("#email").value,r=contactForm.querySelector("#message").value;fetch(t,{method:"POST",body:JSON.stringify({name:c,email:n,subject:a,message:r,grecaptcha_response:e})}).then(e=>{e.ok?(s.innerHTML=' <p class="snackbars-left"><span>Successfully sent!</span></p>',s.classList.add("success"),this.reset(),setTimeout(()=>s.classList.remove("active","success"),2e3)):(s.innerHTML=' <p class="snackbars-left"></span><span>reCAPTCHA is not verified</span></p>',s.classList.add("error"),setTimeout(()=>s.classList.remove("active","error"),2e3))}).catch(()=>{s.innerHTML=' <p class="snackbars-left"></span><span>Aw, snap! Something went wrong.</span></p>',s.classList.add("error"),setTimeout(()=>s.classList.remove("active","error"),2e3)})}}else s.innerHTML=' <p class="snackbars-left"><span>Please, enter correct data.</span></p>',s.classList.add("error"),setTimeout(()=>s.classList.remove("active","error"),2e3)});